  justify-content: flex-end;
  gap: 12px;
}

.btn-cancel {
  background-color: transparent;
  color: var(--on-surface);
  border: 1px solid #444;
}

.btn-delete {
  background-color: var(--error-color);
  color: white;
}

.hidden {
  display: none;
}
