  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
  background-color: #2c2c2c;
  margin-bottom: 20px;
}

.controls {
  margin-top: 10px;
}

button {
  padding: 10px 20px;
  font-size: 1rem;
  border-radius: 4px;
  border: none;
  cursor: pointer;
  transition: opacity 0.2s;
}

button:hover {
  opacity: 0.8;
}

button:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

.trigger {
  background-color: var(--error-color);
  color: white;
}

/* Modal Styles */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: var(--overlay-color);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
}

.modal-content {
  background-color: var(--surface-color);
  padding: 24px;
  border-radius: 12px;
  max-width: 400px;
  width: 90%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.8);
  color: var(--on-surface);
  text-align: left;
}

.modal-title {
  margin-top: 0;
  font-size: 1.25rem;
  font-weight: 600;
}

.modal-description {
  margin-bottom: 24px;
  line-height: 1.5;
  color: #b0b0b0;
}

.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
}

.btn-cancel {
  background-color: transparent;
  color: var(--on-surface);
  border: 1px solid #444;
}

.btn-delete {
  background-color: var(--error-color);
  color: white;
}

.hidden {
  display: none;
}
